/**
 * Custom method for custom view in map-x
 * Parameters for onInit and onClose function ;
 * @param {Object} o Options
 * @param {Object} o.view Map-x view object
 * @param {Object} o.map mapbox-gl map object
 * @param {String} o.idView If of the view
 * @param {String} o.idSource Id of the source
 * @param {Element} o.elLegend Element containing the legend
 *
 */

return {
  onClose: function (o) {
    console.log("Custom view closed");

    /*
     * Remove timer
     */
    window.clearInterval(o.timer);

    /**
     * Remove source
     */
    if (o.map.getLayer(o.idView)) {
      o.map.removeLayer(o.idView);
    }
    if (o.map.getSource(o.idSource)) {
      o.map.removeSource(o.idSource);
    }


  },
  onInit: function (o) {
    console.log("Custom view added");

    var url = "https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_month.geojson";

    getUsgs();

    o.timer = window.setInterval(getUsgs, 900000);


    function getUsgs() {
      fetch(url)
        .then(response => {
          return response.json();
        })
        .then(data => update(data))
        .catch(err => {
          mx.helpers.modal({
            title: "error when fetchng" + url,
            content: err
          });
        });
    }


    /**
     *  Update the data of the source
     */
    function update(data) {
      data = filterData(data);
      data = addGid(data);
      var src = o.map.getSource(o.idSource);
      if (!src) {
        init(data);
      } else {
        src.setData(data);
      }
    }

    /**
     * Check if data is an array and filter magnitudes
     */
    function filterData(data) {

      var isArray = mx.helpers
        .path(data, "features") instanceof Array;

      if (!isArray) {
        console.log("The server didn't returned an array but this :");
        console.log(data.features);
        data.features = [];
      }

      data.features = data.features.filter(function (f) {
        return f.properties.mag >= 5.5;
      });

      data.features = data.features.sort(function (a, b) {
        return b.properties.mag - a.properties.mag;
      });

      return (data);

    }

    function addGid(data) {
      data.features.forEach((f, i) => {
        f.properties.gid = i;
      })
      return data;
    }

    /**
     * Create an empty source and a layer  
     */
    function init(data) {

      /**
       * Set custom source
       */
      o.source = {
        "type": "geojson",
        "data": data
      };


      var stopsMag = [
        [5.5, 5],
        [7, 10],
        [8.5, 20],
        [10, 40],
      ];


      /**
       * Set custom layer
       */
      o.layer = {
        "id": o.idView,
        "type": "circle",
        "source": o.idSource,
        "paint": {
          "circle-color": '#ffce5e',
          "circle-stroke-width": 1,
          "circle-opacity": 1,
          "circle-radius": {
            property: 'mag',
            stops: stopsMag,

          },
        },
        "filter": ["==", "$type", "Point"],
      };

      /**
       * Set custom legend
       */
      o.elLegend.style = "font: 'Helvetica Neue', Arial, Helvetica, sans-serif";

      var url = "https://owncloud.unepgrid.ch/index.php/s/40DDTRqNpb0etmr/download";

      fetch(url)
        .then(r => r.text())
        .then(svg => o.elLegend.innerHTML = svg)
        .catch(e => {

          mx.helpers.modal({
            title: "error when fetchng the legend " + url,
            content: err
          });
        });

      /**
       * Set layer and source
       */
      o.map.addSource(o.idSource, o.source);
      o.map.addLayer(o.layer, "mxlayers");
    }
  }
};

/**
 * Custom method for custom view in MapX
 * Parameters for onInit and onClose function ;
 * @param {Object} o Options
 * @param {Object} o.view Map-x view object
 * @param {Object} o.map mapbox-gl map object
 * @param {String} o.idView If of the view
 * @param {String} o.idSource Id of the source
 * @param {Element} o.elLegend Element containing the legend
 *
 */
return {
  onClose: function (o) {
    /**
     * Remove source
     */
    o.onRemove();

  },
  onInit: function (o) {
    const h = mx.helpers;
    const el = h.el;

    const url = "https://mapproxy.terrascope.be/mapproxy/wmts/esa-worldcover-map-10m-2021-v2_map/webmercator/{z}/{x}/{y}.png"
    const categories = [{
      label: "Tree cover",
      color: "rgb(0,100,0)"
    },
    {
      label: "Shrubland",
      color: "rgb(255, 187, 34)"
    },
    {
      label: "Grassland",
      color: "rgb(255, 255, 76)"
    },
    {
      label: "Cropland",
      color: "rgb(240, 150, 255)"
    },
    {
      label: "Built-up",
      color: "rgb(250, 0, 0)"
    },
    {
      label: "Bare/sparse vegetation",
      color: "rgb(180, 180, 180)"
    },
    {
      label: "Snow and Ice",
      color: "rgb(240, 240, 240)"
    },
    {
      label: "Permanent water bodies",
      color: "rgb(0, 100, 200)"
    },
    {
      label: "Herbaceous wetland",
      color: "rgb(0, 150, 160)"
    },
    {
      label: "Mangroves",
      color: "rgb(0, 207, 117)"
    },
    {
      label: "Moss and lichen",
      color: "rgb(250, 230, 160)"
    }
    ];

    setLegend(categories);

    /**
     * Set custom source
     */
    o.source = {
      type: 'raster',
      tiles: [url],
      tileSize: 512
    };

    /**
     * Set custom layer
     */
    o.layer = {
      id: o.idView,
      type: "raster",
      source: o.idSource,
      paint: {}
    };

    /**
     * Set layer and source
     */
    o.map.addSource(o.idSource, o.source);
    o.map.addLayer(o.layer, mx.settings.layerBefore);


    /**
     * Helpers
     */
    function setLegend(categories) {
      if (h.isElement(o.elLegend)) {

        var elLegendContent = el("div", {
          class: ['mx-legend-box'],
          style: {
            display: "flex",
            flexDirection: "column"
          }
        },
          el('div', 'Land Cover Class', {
            style: {
              paddingLeft: '10px',
              marginBottom: '10px'
            }
          }),
          categories.map(e => {
            return el('div', {
              style: {
                display: 'flex',
                flexDirection: 'row',
                justifyContent: 'flex-start',
                alignItems: 'center'
              }
            },
              el('span', {
                style: {
                  width: '20px',
                  height: '20px',
                  marginRight: '5px',
                  background: e.color
                }
              }),
              el('span', e.label));
          }));
        o.elLegend.appendChild(elLegendContent);
      }
    }

    /**
     * Remove added layers
     */
    o.onRemove = function () {
      var layer = o.map.getLayer(o.idView);
      var source = o.map.getSource(o.idSource);
      if (layer) {
        o.map.removeLayer(o.idView);
      }
      if (source) {
        o.map.removeSource(o.idSource);
      }
    };

  }
};

function handler() {
  const local = { clean: async () => { } };

  const SOURCE_ID = "mx_dxbcn_smwnh_7hrvm_ri0me_3fm94";
  const WATER = "j0_water_scarcity";
  const NUTRITION = "j0_child_nutrition";

  const NO_DATA = "#A9A9A9";
  const WB = [1.5, 4.7, 7.4];
  const NB = [3.6, 5.8, 8.3];

  const COLORS = [
    ["#D3D3D3", "#92BDBD", "#4FA6A6", "#0E9191"],
    ["#B59FB1", "#7D8F9F", "#447E8C", "#0C6D7A"],
    ["#966A90", "#685F81", "#385471", "#0A4963"],
    ["#78376E", "#533163", "#2D2B57", "#08254B"]
  ];

  const value = (field) => [
    "case",
    ["has", field],
    ["to-number", ["get", field], -999999],
    -999999
  ];

  const classify = (v, breaks, colors) => [
    "case",
    ["<=", v, breaks[0]], colors[0],
    ["<=", v, breaks[1]], colors[1],
    ["<=", v, breaks[2]], colors[2],
    colors[3]
  ];

  return {
    onInit: async function (cc) {
      const legend = buildLegend();
      cc.setLegend(legend.root);
      legend.setStatus("Loading source...");

      const tileBase = getTileBase(cc.map);

      if (!tileBase) {
        legend.setStatus("Could not determine the MapX tile endpoint.");
        return;
      }

      const tileUrl =
        tileBase +
        "?idSource=" + encodeURIComponent(SOURCE_ID) +
        "&attribute=" + encodeURIComponent(WATER) +
        "&attributes=" + encodeURIComponent(NUTRITION);

      const w = value(WATER);
      const n = value(NUTRITION);

      const noData = [
        "any",
        ["==", w, -999999],
        ["==", n, -999999],
        ["==", ["get", WATER], ""],
        ["==", ["get", NUTRITION], ""]
      ];

      const rows = COLORS.map((colors) =>
        classify(w, WB, colors)
      );

      const fillColor = [
        "case",
        noData, NO_DATA,
        ["<=", n, NB[0]], rows[0],
        ["<=", n, NB[1]], rows[1],
        ["<=", n, NB[2]], rows[2],
        rows[3]
      ];

      cc.addSource({
        type: "vector",
        tiles: [tileUrl],
        minzoom: 0,
        maxzoom: 22
      });

      if (cc.isClosed()) return;

      cc.addLayer({
        id: cc.idView,
        type: "fill",
        source: cc.idSource,
        "source-layer": SOURCE_ID,
        filter: ["==", ["geometry-type"], "Polygon"],
        paint: {
          "fill-color": fillColor,
          "fill-opacity": 0.85,
          "fill-antialias": true
        }
      });

      const onSourceData = (e) => {
        if (
          e.sourceId === cc.idSource &&
          e.isSourceLoaded
        ) {
          legend.setStatus("");
        }
      };

      const onError = (e) => {
        if (
          e.sourceId &&
          e.sourceId !== cc.idSource
        ) return;

        const message =
          e.error && e.error.message
            ? e.error.message
            : "Vector source error. Check the browser console.";

        legend.setStatus(message);
        console.error("MapX bivariate view error", e);
      };

      cc.map.on("sourcedata", onSourceData);
      cc.map.on("error", onError);

      local.clean = async () => {
        cc.map.off("sourcedata", onSourceData);
        cc.map.off("error", onError);
      };
    },

    onClose: async function () {
      await local.clean();
    }
  };

  function getTileBase(map) {
    try {
      const sources =
        (map.getStyle() || {}).sources || {};

      for (const source of Object.values(sources)) {
        if (
          !source ||
          source.type !== "vector" ||
          !Array.isArray(source.tiles)
        ) continue;

        const tile = source.tiles.find(
          (t) =>
            typeof t === "string" &&
            t.indexOf("/get/tile/") !== -1
        );

        if (tile) {
          return tile.split("?")[0];
        }
      }
    } catch (e) {
      console.warn(
        "Tile endpoint discovery failed",
        e
      );
    }

    const host = window.location.hostname;

    if (
      host === "mapx.org" ||
      host.endsWith(".mapx.org")
    ) {
      return (
        window.location.protocol +
        "/" +
        "/" +
        "api.mapx.org/get/tile/{x}/{y}/{z}.mvt"
      );
    }

    return null;
  }

  function buildLegend() {
    const root = document.createElement("div");

    Object.assign(root.style, {
      width: "100%",
      maxWidth: "190px",
      padding: "4px 2px 6px",
      fontSize: "10px",
      boxSizing: "border-box"
    });

    const body = document.createElement("div");

    Object.assign(body.style, {
      display: "flex",
      alignItems: "center",
      gap: "6px"
    });

    const y = document.createElement("div");

    y.textContent = "Child nutrition ↑";

    Object.assign(y.style, {
      writingMode: "vertical-rl",
      transform: "rotate(180deg)",
      whiteSpace: "nowrap"
    });

    const block = document.createElement("div");
    const matrix = document.createElement("div");

    Object.assign(matrix.style, {
      display: "grid",
      gridTemplateColumns: "repeat(4, 27px)",
      gap: "1px"
    });

    [...COLORS]
      .reverse()
      .flat()
      .forEach((color) => {
        const cell = document.createElement("div");

        Object.assign(cell.style, {
          width: "27px",
          height: "27px",
          backgroundColor: color,
          border: "1px solid rgba(90,90,90,0.18)",
          boxSizing: "border-box"
        });

        matrix.appendChild(cell);
      });

    const x = document.createElement("div");

    x.textContent = "Water scarcity →";

    Object.assign(x.style, {
      width: "111px",
      textAlign: "center",
      marginTop: "3px"
    });

    block.appendChild(matrix);
    block.appendChild(x);

    body.appendChild(y);
    body.appendChild(block);

    root.appendChild(body);

    const noData = document.createElement("div");

    Object.assign(noData.style, {
      display: "flex",
      alignItems: "center",
      gap: "6px",
      marginTop: "7px"
    });

    const swatch = document.createElement("span");

    Object.assign(swatch.style, {
      width: "14px",
      height: "14px",
      display: "inline-block",
      backgroundColor: NO_DATA,
      border: "1px solid rgba(90,90,90,0.3)"
    });

    const label = document.createElement("span");
    label.textContent = "No data";

    noData.appendChild(swatch);
    noData.appendChild(label);

    root.appendChild(noData);

    const status = document.createElement("div");

    Object.assign(status.style, {
      marginTop: "6px",
      fontSize: "9px",
      opacity: "0.75",
      wordBreak: "break-word"
    });

    root.appendChild(status);

    return {
      root,

      setStatus: (message) => {
        status.textContent = message || "";
        status.style.display =
          message ? "block" : "none";
      }
    };
  }
}

/**
 * Custom code view handler
 *
 * Disasters (polygons, choropleth on j0_disasters) rendered below,
 * IDPs (points, hollow proportional circles on j0_idp) rendered above.
 *
 * Sources are referenced by id only (no view id), relying on the tile API's
 * idSource-only special case.
 */
function handler() {
  const { mx } = window;
  const { el, svg, getApiUrl, modulesLoad } = mx.helpers;

  const idSourceDisasters = "mx_sficl_t5pkr_lrrkq_jfmc2_zdgkx";
  const idSourceIdp = "mx_26jol_qxvey_u3grj_dswod_vov97";

  // Shared break boundaries. Placeholder classes: no stats were available,
  // values are modeled on the reference legend only.
  const disasterBreaks = [100, 300, 700, 1200, 2000];
  const idpBreaks = [10000, 100000, 1000000, 3000000, 50000000];
  const idpRadii = [4, 8, 14, 20, 28];
  const idpStrokeColor = "#8f2033";

  const local = {
    idLayerDisasters: null,
    idLayerIdp: null,
    idSrcDisasters: null,
    idSrcIdp: null,
    disasterColors: null,
    clean: async () => { },
  };

  return {
    /**
     * On init callback
     * @param {Object} cc Custom code view runtime
     */
    onInit: async function (cc) {
      cc.setLegend(el("span", "Please wait..."));

      const [chroma] = await modulesLoad(["chroma-js"]);

      if (cc.isClosed()) {
        console.warn("View has been closed during module load, cancel");
        return;
      }

      local.disasterColors = chroma
        .scale(["#f7f4c3", "#1f6f6b"])
        .mode("lab")
        .colors(disasterBreaks.length);

      /**
       * Naming contract used by MapX click / highlight handlers:
       * - layer id: <idView>@<suffix> ('@' = sublayer separator)
       * - map source id: starts with <idView>
       */
      local.idLayerDisasters = `${cc.idView}@disasters`;
      local.idLayerIdp = `${cc.idView}@idp`;
      local.idSrcDisasters = `${cc.idView}-SRC-disasters`;
      local.idSrcIdp = `${cc.idView}-SRC-idp`;

      /**
       * Polygons (bottom)
       */
      cc.map.addSource(local.idSrcDisasters, {
        type: "vector",
        tiles: tileUrl(idSourceDisasters, [
          "iso3cd",
          "name_en",
          "j0_disasters",
        ]),
      });

      cc.map.addLayer(
        {
          id: local.idLayerDisasters,
          type: "fill",
          source: local.idSrcDisasters,
          "source-layer": idSourceDisasters,
          paint: {
            "fill-color": buildStepColor(
              "j0_disasters",
              disasterBreaks,
              local.disasterColors,
            ),
            "fill-opacity": 0.85,
            "fill-outline-color": "rgba(80,80,80,0.4)",
          },
        },
        cc.before,
      );

      /**
       * Centroids / circles (top), hollow, sized by j0_idp
       */
      cc.map.addSource(local.idSrcIdp, {
        type: "vector",
        tiles: tileUrl(idSourceIdp, ["iso3cd", "name_en", "j0_idp"]),
      });

      cc.map.addLayer(
        {
          id: local.idLayerIdp,
          type: "circle",
          source: local.idSrcIdp,
          "source-layer": idSourceIdp,
          paint: {
            "circle-radius": buildStepRadius("j0_idp", idpBreaks, idpRadii),
            "circle-color": "rgba(0,0,0,0)",
            "circle-stroke-color": idpStrokeColor,
            "circle-stroke-width": 2,
            "circle-stroke-opacity": 1,
          },
        },
        cc.before,
      );

      cc.setLegend(buildLegend());

      local.clean = async () => {
        for (const id of [local.idLayerDisasters, local.idLayerIdp]) {
          if (id && cc.map.getLayer(id)) {
            cc.map.removeLayer(id);
          }
        }
        for (const id of [local.idSrcDisasters, local.idSrcIdp]) {
          if (cc.map.getSource(id)) {
            cc.map.removeSource(id);
          }
        }
      };
    },

    /**
     * On close callback
     */
    onClose: async function () {
      await local.clean();
    },
  };

  /**
   * Build a maplibre "step" color expression from breaks/colors arrays.
   * ["step", ["to-number", ["get", field]], colors[0], breaks[0], colors[1], ..., colors[last]]
   */
  function buildStepColor(field, breaks, colors) {
    const expr = ["step", ["to-number", ["get", field]], colors[0]];
    for (let i = 0; i < breaks.length - 1; i++) {
      expr.push(breaks[i], colors[i + 1]);
    }
    return expr;
  }

  /**
   * Build a maplibre "step" radius expression from breaks/radii arrays.
   * Below the first break, radius is 0 (no marker for empty/zero values).
   */
  function buildStepRadius(field, breaks, radii) {
    const expr = ["step", ["to-number", ["get", field]], 0];
    for (let i = 0; i < breaks.length; i++) {
      expr.push(breaks[i], radii[i]);
    }
    return expr;
  }

  /**
   * Tile url
   */
  function tileUrl(idSource, attributes) {
    const url = `${getApiUrl("getTile")}?idSource=${idSource}&attributes=${attributes.join(",")}&timestamp=${Date.now()}`;
    return [url, url];
  }

  /**
   * Build the static double legend (disasters choropleth + IDP proportional
   * hollow circles), rendered as SVG icons + text rows, non-interactive.
   */
  function buildLegend() {
    const maxRadius = idpRadii[idpRadii.length - 1];

    const rowLabel = (breaks, i) => {
      const min = i === 0 ? 0 : breaks[i - 1];
      return `${min.toLocaleString()} - ${breaks[i].toLocaleString()}`;
    };

    const legendRow = (icon, label, iconColWidth = 80) =>
      el(
        "div",
        {
          style: {
            display: "flex",
            alignItems: "center",
            gap: "8px",
            margin: "2px 0",
          },
        },
        [
          el(
            "div",
            {
              style: {
                width: `${iconColWidth}px`,
                display: "flex",
                justifyContent: "start",
              },
            },
            [icon],
          ),
          el("span", label),
        ],
      );

    const legendTitle = (text) =>
      el(
        "div",
        {
          style: {
            fontWeight: "bold",
            marginTop: "8px",
            marginBottom: "4px",
          },
        },
        text,
      );

    const disasterRows = disasterBreaks.map((b, i) =>
      legendRow(
        svg("svg", { width: 18, height: 18 }, [
          svg("rect", {
            width: 18,
            height: 18,
            fill: local.disasterColors[i],
            stroke: "#999",
            "stroke-width": 1,
          }),
        ]),
        rowLabel(disasterBreaks, i),
      ),
    );

    const idpRows = idpBreaks.map((b, i) => {
      const r = idpRadii[i];
      const iconSize = r * 2 + 4;
      const cxy = iconSize / 2;
      return legendRow(
        svg("svg", { width: iconSize, height: iconSize }, [
          svg("circle", {
            cx: cxy,
            cy: cxy,
            r,
            fill: "none",
            stroke: idpStrokeColor,
            "stroke-width": 2,
          }),
        ]),
        rowLabel(idpBreaks, i),
      );
    });

    return el("div", { style: { fontSize: "12px", lineHeight: "1.3" } }, [
      legendTitle("Disasters"),
      ...disasterRows,
      legendTitle("IDPs"),
      ...idpRows,
    ]);
  }
}
